-- ICT371 Question 4: Clinic Appointment Scheduling (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q04_clinic; USE ict371_q04_clinic;
CREATE TABLE Patients(patient_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL);
CREATE TABLE Doctors(doctor_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL);
CREATE TABLE appointments(appointment_id BIGINT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_day DATE NOT NULL,slot_time TIME NOT NULL,status ENUM('BOOKED','ATTENDED','CANCELLED') NOT NULL DEFAULT 'BOOKED',FOREIGN KEY(patient_id) REFERENCES Patients(patient_id),FOREIGN KEY(doctor_id) REFERENCES Doctors(doctor_id),CHECK(slot_time IN ('09:00:00','10:00:00','11:00:00','12:00:00')));
CREATE TABLE clinic_summary(summary_date DATE PRIMARY KEY,booked_count BIGINT NOT NULL,attended_count BIGINT NOT NULL,cancelled_count BIGINT NOT NULL);
INSERT INTO Patients(full_name) VALUES('Mwaka Phiri'),('Tapiwa Zulu'),('Chanda Banda'); INSERT INTO Doctors(full_name) VALUES('Dr. Kunda'),('Dr. Mbewe'),('Dr. Lungu');
DELIMITER $$
CREATE FUNCTION fn_daily_load(p_doctor_id INT,p_day DATE) RETURNS INT DETERMINISTIC READS SQL DATA BEGIN DECLARE v_count INT; IF NOT EXISTS(SELECT 1 FROM Doctors WHERE doctor_id=p_doctor_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown doctor'; END IF; SELECT COUNT(*) INTO v_count FROM appointments WHERE doctor_id=p_doctor_id AND appointment_day=p_day AND status<>'CANCELLED'; RETURN v_count; END$$
CREATE TRIGGER trg_appointment_slot BEFORE INSERT ON appointments FOR EACH ROW BEGIN IF NEW.appointment_day<CURRENT_DATE OR NEW.slot_time NOT IN ('09:00:00','10:00:00','11:00:00','12:00:00') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Past date or unsupported slot'; END IF; IF NEW.status<>'CANCELLED' AND EXISTS(SELECT 1 FROM appointments WHERE doctor_id=NEW.doctor_id AND appointment_day=NEW.appointment_day AND slot_time=NEW.slot_time AND status<>'CANCELLED') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Doctor slot already occupied'; END IF; END$$
CREATE TRIGGER trg_appointment_slot_update BEFORE UPDATE ON appointments FOR EACH ROW BEGIN IF NEW.appointment_day<CURRENT_DATE OR NEW.slot_time NOT IN ('09:00:00','10:00:00','11:00:00','12:00:00') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Past date or unsupported slot'; END IF; IF NEW.status<>'CANCELLED' AND EXISTS(SELECT 1 FROM appointments WHERE doctor_id=NEW.doctor_id AND appointment_day=NEW.appointment_day AND slot_time=NEW.slot_time AND status<>'CANCELLED' AND appointment_id<>OLD.appointment_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Doctor slot already occupied'; END IF; END$$
CREATE PROCEDURE pr_book_appointment(IN p_patient_id INT,IN p_doctor_id INT,IN p_day DATE,IN p_slot TIME) BEGIN IF NOT EXISTS(SELECT 1 FROM Patients WHERE patient_id=p_patient_id) OR NOT EXISTS(SELECT 1 FROM Doctors WHERE doctor_id=p_doctor_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown patient or doctor'; END IF; IF p_day<CURRENT_DATE OR p_slot NOT IN ('09:00:00','10:00:00','11:00:00','12:00:00') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid date or slot'; END IF; INSERT INTO appointments(patient_id,doctor_id,appointment_day,slot_time,status) VALUES(p_patient_id,p_doctor_id,p_day,p_slot,'BOOKED'); END$$
CREATE PROCEDURE pr_refresh_clinic_summary(IN p_day DATE) BEGIN INSERT INTO clinic_summary(summary_date,booked_count,attended_count,cancelled_count) SELECT p_day,SUM(status='BOOKED'),SUM(status='ATTENDED'),SUM(status='CANCELLED') FROM appointments WHERE appointment_day=p_day ON DUPLICATE KEY UPDATE booked_count=VALUES(booked_count),attended_count=VALUES(attended_count),cancelled_count=VALUES(cancelled_count); END$$
DELIMITER ;
INSERT INTO appointments(patient_id,doctor_id,appointment_day,slot_time,status) VALUES(1,1,CURRENT_DATE,'09:00','BOOKED'),(2,1,CURRENT_DATE,'10:00','ATTENDED'),(3,2,CURRENT_DATE,'09:00','CANCELLED'),(1,2,CURRENT_DATE,'11:00','BOOKED'),(2,3,CURRENT_DATE,'12:00','BOOKED'),(3,3,CURRENT_DATE+INTERVAL 1 DAY,'09:00','BOOKED');
CREATE VIEW v_today_appointments AS SELECT a.appointment_id,p.full_name patient_name,d.full_name doctor_name,a.slot_time FROM appointments a JOIN Patients p ON p.patient_id=a.patient_id JOIN Doctors d ON d.doctor_id=a.doctor_id WHERE a.appointment_day=CURRENT_DATE AND a.status='BOOKED';
CREATE INDEX ix_appointments_day_doctor ON appointments(appointment_day,doctor_id);
EXPLAIN SELECT appointment_id,patient_id,slot_time FROM appointments WHERE appointment_day=CURRENT_DATE AND doctor_id=1;
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_refresh_clinic_summary ON SCHEDULE EVERY 1 DAY STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL 1 DAY,'01:00:00')) DO CALL pr_refresh_clinic_summary(CURRENT_DATE-INTERVAL 1 DAY);
